    "mf4abf68e2926": "공개 범위",
    "m82b7cf40b5e6": "현황",
    "m4f16392768a7": "본인은 확인합니다: 프롬프트 단어, 매개변수, 재료 및 결과가 공개되며 이후에 성공적으로 저장된 수정 사항도 공개됩니다. 먼저 콘텐츠에 비밀이 포함되어 있는지 확인하세요. 읽기 전용은 복사를 방지하지 않으며 링크를 닫거나 재설정하면 얻은 콘텐츠와 복사본을 복구할 수 없습니다.",
